# --------------------------------------------------------------------------
# durable-state comparison primitives
# --------------------------------------------------------------------------
_ISO_PATTERN = re.compile(
    r"^\s*(\d{4})-(\d{1,2})-(\d{1,2})"
    r"(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?)?"
    r"\s*(Z|[+-]\d{2}:?\d{2})?\s*$"
)


def _plain_number(value: Any) -> float | None:
    """Return *value* as a float when it is a non-boolean JSON number."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def _text(value: Any) -> str:
    """Return the comparison text of *value*, mapping both nulls onto ``""``."""
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value).strip()


def _values_match(actual: Any, expected: Any) -> bool:
    """Compare one field value exactly, allowing cross-type equal scalars."""
    if isinstance(expected, bool):
        return isinstance(actual, bool) and actual is expected
    if isinstance(expected, (int, float)) and not isinstance(expected, bool):
        actual_number = _plain_number(actual)
        return actual_number is not None and actual_number == float(expected)
    if isinstance(expected, str) and isinstance(actual, (int, float)) and not isinstance(actual, bool):
        expected_number = _plain_number(expected)
        return expected_number is not None and expected_number == float(actual)
    if isinstance(actual, str) and isinstance(expected, (int, float)) and not isinstance(expected, bool):
        actual_number = _plain_number(actual)
        return actual_number is not None and actual_number == float(expected)
    return type(actual) is type(expected) and actual == expected


def field_text(record: Mapping[str, Any], key: str) -> str:
    """Return *key* rendered for a set comparison on *record*."""
    for name in stamp_keys(key):
        if name in record:
            return _text(record.get(name))
    return ""


def stamp_keys(key: str) -> tuple[str, ...]:
    """Return the storage names a check-level field name may map onto."""
    snake = re.sub(r"(?<!^)(?=[A-Z])", "_", key).lower()
    camel = re.sub(r"_([a-z])", lambda match: match.group(1).upper(), key)
    names: list[str] = []
    for name in (key, snake, camel):
        if name not in names:
            names.append(name)
    return tuple(names)


def date_text(value: Any) -> str:
    """Return an ISO calendar date for *value*, or the trimmed text itself."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    match = _ISO_PATTERN.match(raw)
    if not match:
        return raw
    year, month, day = (int(match.group(index)) for index in (1, 2, 3))
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return raw


def datetime_value(value: Any) -> datetime | None:
    """Return *value* as a timezone-aware instant, or ``None`` when unusable."""
    raw = str(value or "").strip()
    if not raw:
        return None
    match = _ISO_PATTERN.match(raw)
    if not match:
        return None
    year, month, day = (int(match.group(index)) for index in (1, 2, 3))
    hour = int(match.group(4) or 0)
    minute = int(match.group(5) or 0)
    second = int(match.group(6) or 0)
    offset = match.group(7) or ""
    try:
        moment = datetime(year, month, day, hour, minute, second)
    except ValueError:
        return None
    if offset in ("Z", "z"):
        return moment.replace(tzinfo=timezone.utc)
    if offset:
        sign = 1 if offset[0] == "+" else -1
        digits = offset[1:].replace(":", "")
        delta = timezone(
            sign * timedelta(hours=int(digits[:2]), minutes=int(digits[2:4]))
        )
        return moment.replace(tzinfo=delta).astimezone(timezone.utc)
    return moment.replace(tzinfo=timezone.utc)


def is_after(value: Any, boundary: Any) -> bool:
    """Return whether *value* names a strictly later instant than *boundary*."""
    moment = datetime_value(value)
    base = datetime_value(boundary)
    if moment is None or base is None:
        return False
    return moment > base


def is_at_or_after(value: Any, boundary: Any) -> bool:
    """Return whether *value* names the same or a later instant than *boundary*."""
    moment = datetime_value(value)
    base = datetime_value(boundary)
    if moment is None or base is None:
        return False
    return moment >= base
